(()=>{function s(i,n,t){let r=i.$data(n);Object.keys(t).forEach(o=>{r[o]=t[o]==="!!"?!r[o]:t[o]})}function f(i){i.magic("emit",()=>(n,t={})=>{(Array.isArray(n)?n:[[n,t]]).forEach(([o,e={}])=>{if(!o)return;(typeof o=="string"?document.querySelectorAll(o):[o]).forEach(c=>{i.closestRoot(c)&&s(i,c,e)})})})}document.addEventListener("alpine:init",()=>window.Alpine.plugin(f));})();
